import './cloud-sync.js';
import{DATA_TRACKS,DATA_CHAIN,DATA_DIAGNOSTIC,recommendDataTrack,graphDifference,dataSummary,createBlankDataLearner}from'./datareason-data.js?v=datareason2';

const $=s=>document.querySelector(s),storageKey='mathlab-datareason-v1',memory={};
function blankStore(){return{a:createBlankDataLearner(),b:createBlankDataLearner(),learner:'a'}}
function readStore(){try{return JSON.parse(localStorage.getItem(storageKey))||blankStore()}catch{return memory.data||blankStore()}}
let store=readStore(),learner=store.learner||'a',state=store[learner]||createBlankDataLearner(),hintLevel=0,errors=0,sessionMissionId=null,work={};
function ensureState(){const blank=createBlankDataLearner();state={...blank,...state,diagnostic:{...blank.diagnostic,...state.diagnostic},missions:{...state.missions},sessions:{...state.sessions},evidence:{...blank.evidence,...state.evidence},family:{...blank.family,...state.family}}}
function save(){state.updatedAt=new Date().toISOString();store={...readStore(),[learner]:state,learner};memory.data=store;try{localStorage.setItem(storageKey,JSON.stringify(store));$('#saveStatus').textContent='Saved offline · cloud sync follows parent sign-in'}catch{$('#saveStatus').textContent='Progress lasts until this page closes.'}}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function feedback(text,type=''){const el=$('#feedback');el.textContent=text;el.className='feedback '+type}
function track(){return DATA_TRACKS[state.track||'explorer']}
function done(i){return Boolean(state.missions[DATA_CHAIN.missions[i].id]?.complete)}
function unlocked(i){return i===0||done(i-1)}
function mark(dim,independent=true){if(independent)state.evidence[dim]='independent';else if(state.evidence[dim]==='unknown')state.evidence[dim]='learning'}
function loadSession(id){sessionMissionId=id;const saved=state.sessions[id]||{errors:0,hints:0,work:{}};errors=Number(saved.errors)||0;hintLevel=Number(saved.hints)||0;work=saved.work||{}}
function saveSession(nextWork=work){if(!sessionMissionId)return;work=nextWork;state.sessions[sessionMissionId]={errors,hints:hintLevel,work};save()}
function miss(message){errors++;saveSession();feedback(message,'try')}
function complete(i,dims=[],pending=false,preview=false){const m=DATA_CHAIN.missions[i];state.missions[m.id]={complete:!preview,preview,errors,hints:hintLevel,completedAt:new Date().toISOString(),track:state.track};dims.forEach(d=>mark(d,errors===0&&hintLevel===0&&!preview));if(pending){state.retestDue=Date.now()+20*60*60*1000;state.evidence.transfer=state.evidence.transfer==='unknown'?'learning':state.evidence.transfer}if(!preview&&i<4)state.activeMission=i+1;delete state.sessions[m.id];errors=0;hintLevel=0;work={};sessionMissionId=null;save();setTimeout(render,420)}
function hint(text){return hintLevel?`<div class="hint-box">${esc(text)}</div>`:''}
function controls(){return `<div class="answer-row"><button class="secondary" data-action="hint">Give me one hint</button></div>`}
function mix(correct,others){const values=[...new Set([correct,...others])],shift=String(correct).length%values.length;return values.slice(shift).concat(values.slice(0,shift))}
function textChoices(correct,others,attr){return `<div class="answer-grid">${mix(correct,others).map(v=>`<button class="choice" data-${attr}="${v===correct?'correct':'wrong'}">${esc(v)}</button>`).join('')}</div>`}
function numberChoices(correct,others,attr){return `<div class="answer-grid number-choices">${mix(correct,others).map(v=>`<button class="choice" data-${attr}="${v}">${v}</button>`).join('')}</div>`}
function graphModel(g,reveal=false){const max=Math.max(...g.values),top=Math.ceil(max/g.scale)*g.scale,ticks=Array.from({length:top/g.scale+1},(_,i)=>i*g.scale).reverse();return `<div class="bar-chart" role="img" aria-label="Bar chart. Axis counts by ${g.scale}."><div class="chart-body"><div class="chart-axis">${ticks.map(n=>`<span>${n}</span>`).join('')}</div><div class="chart-bars" style="--chart-steps:${top/g.scale};--bar-count:${g.values.length}">${g.values.map((v,i)=>`<div class="bar-slot"><div class="data-bar" style="height:${v/top*100}%"><b>${reveal?v:''}</b></div><span>${esc(g.labels[i])}</span></div>`).join('')}</div></div><p class="model-caption">Each grid step is worth <strong>${g.scale}</strong>. ${reveal?'Exact values are shown.':'Read the scale before comparing the bars.'}</p></div>`}
function dataModel(p,sorted=false){const values=sorted?[...p.data].sort((a,b)=>a-b):p.data;return `<div class="data-row ${sorted?'sorted':''}" role="img" aria-label="Data values ${values.join(', ')}">${values.map(n=>`<span>${n}</span>`).join('')}</div><p class="model-caption">${sorted?'Now look for the middle, the spread, or the value that repeats most.':'Organize the values before choosing a summary.'}</p>`}
function renderDiagnostic(){const d=state.diagnostic;if(d.index>=DATA_DIAGNOSTIC.length){state.track=state.track||recommendDataTrack(d.score);const t=track();$('#activity').innerHTML=`<div class="complete-card"><div class="big-check">✓</div><p class="eyebrow">STARTING DEPTH FOUND</p><h3>${t.label}</h3><p>${t.description}</p><p class="microcopy">This chooses useful data challenges. It is not a grade label.</p><button class="primary" data-action="start">Read a graph →</button></div>`;return}const q=DATA_DIAGNOSTIC[d.index];$('#activity').innerHTML=`<div class="diagnostic-progress"><span style="width:${d.index/DATA_DIAGNOSTIC.length*100}%"></span></div><p class="eyebrow">QUESTION ${d.index+1} OF ${DATA_DIAGNOSTIC.length}</p><h3>${esc(q.prompt)}</h3><div class="answer-grid">${q.choices.map((x,i)=>`<button class="choice" data-diagnostic="${i}">${esc(x)}</button>`).join('')}</div><p class="microcopy">No timer. Use only the evidence in the question.</p>`;document.querySelectorAll('[data-diagnostic]').forEach(b=>b.onclick=()=>{const correct=Number(b.dataset.diagnostic)===q.answer;d.answers.push({id:q.id,correct});if(correct)d.score++;d.index++;feedback(correct?'Good evidence reading.':q.why,correct?'good':'try');save();setTimeout(()=>{feedback('');render()},450)})}
function renderGraph(){const p=track().graph,reveal=Boolean(work.reveal);if(!work.answer){$('#activity').innerHTML=`<p class="eyebrow">SCALE → VALUE → DIFFERENCE</p><h3>${esc(p.title)}</h3>${graphModel(p,reveal)}<p class="prompt">${esc(p.prompt)}</p>${numberChoices(p.answer,[Math.abs(p.compare[0]-p.compare[1]),p.values[p.compare[0]]+p.values[p.compare[1]]],'graph-answer')}<div class="answer-row"><button class="secondary" data-action="show-values">${reveal?'Exact values shown':'Show exact bar values'}</button></div>${controls()}${hint(`Count by ${p.scale} on the axis. Find both bar values, then subtract the smaller from the larger.`)}`;document.querySelectorAll('[data-graph-answer]').forEach(b=>b.onclick=()=>{const answer=Number(b.dataset.graphAnswer);if(answer===p.answer&&graphDifference(p)===answer){work={...work,answer:true};saveSession();feedback('Correct difference. Now prove it with the exact values.','good');setTimeout(renderMission,350)}else miss('First translate each bar height using the axis scale. Then compare the two values.')})}else{$('#activity').innerHTML=`<p class="eyebrow">PROVE THE DIFFERENCE</p><h3>${esc(p.prompt.replace('?',` ${p.answer}.`))}</h3>${graphModel(p,true)}${textChoices(p.proof,p.decoys,'graph-proof')}${controls()}${hint('A complete proof names both exact values and subtracts them in the correct order.')}`;document.querySelectorAll('[data-graph-proof]').forEach(b=>b.onclick=()=>{if(b.dataset.graphProof==='correct'){feedback('Yes. You used the scale, the values, and subtraction.','good');complete(1,['scale'])}else miss('A bar’s grid height is not always its value. Check the scale and the operation.')})}}
function renderSummary(){const p=track().summary,sorted=Boolean(work.sorted);if(!work.answer){$('#activity').innerHTML=`<p class="eyebrow">ORGANIZE → NOTICE → NAME</p><h3>Find the ${esc(p.kind)} of this data set.</h3>${dataModel(p,sorted)}${numberChoices(p.answer,[Math.max(...p.data),Math.min(...p.data)],'summary-answer')}<div class="answer-row"><button class="secondary" data-action="sort-data">${sorted?'Values are in order':'Put values in order'}</button></div>${controls()}${hint(p.kind==='mode'?'The mode is the value that appears most often.':p.kind==='range'?'The range is greatest value minus least value.':'The median is the middle value after ordering the set.')}`;document.querySelectorAll('[data-summary-answer]').forEach(b=>b.onclick=()=>{const answer=Number(b.dataset.summaryAnswer);if(answer===p.answer&&dataSummary(p.data,p.kind)===answer){work={...work,answer:true};saveSession();feedback(`Correct ${p.kind}. Now explain how the data proves it.`,'good');setTimeout(renderMission,350)}else miss(`Organize the values, then use the meaning of ${p.kind}.`)})}else{$('#activity').innerHTML=`<p class="eyebrow">PROVE THE SUMMARY</p><h3>The ${esc(p.kind)} is ${p.answer}. Why?</h3>${dataModel(p,true)}${textChoices(p.proof,p.decoys,'summary-proof')}${controls()}${hint(`Choose the explanation that uses the exact data and the correct meaning of ${p.kind}.`)}`;document.querySelectorAll('[data-summary-proof]').forEach(b=>b.onclick=()=>{if(b.dataset.summaryProof==='correct'){feedback(`Yes. That is what the ${p.kind} tells us about this set.`,'good');complete(2,['summary'])}else miss(`Check the definition of ${p.kind}; the largest or first value is not automatically the answer.`)})}}
function renderClaim(){const p=track().claim;$('#activity').innerHTML=`<p class="eyebrow">WHAT DOES THE EVIDENCE REALLY SUPPORT?</p><h3>${esc(p.context)}</h3><div class="claim-boundary"><strong>Evidence boundary</strong><span>Use only this observed group or sample. Do not add “everyone,” “always,” or a cause the data did not test.</span></div><p class="prompt">Which conclusion is fair?</p>${textChoices(p.answer,p.decoys,'claim-answer')}${controls()}${hint('A fair conclusion stays inside the people, days, or projects actually observed.')}`;document.querySelectorAll('[data-claim-answer]').forEach(b=>b.onclick=()=>{if(b.dataset.claimAnswer==='correct'){feedback('Yes. The conclusion matches the evidence without stretching beyond it.','good');complete(3,['claim'],true)}else miss('That claim says more than the sample can prove. Keep the conclusion inside the observed evidence.')})}
function renderFresh(){const due=state.retestDue||Date.now()+20*60*60*1000,ready=Date.now()>=due;if(!ready&&!state.previewFresh){const hours=Math.max(1,Math.ceil((due-Date.now())/3600000));$('#activity').innerHTML=`<div class="lock-card"><p class="eyebrow">FRESH CHECK</p><strong>Return after the method has faded from memory.</strong><p>About ${hours} hours remain. Waiting checks whether ${learner==='a'?'Ella':'Mila'} can rebuild the reasoning with new data.</p><button class="secondary" data-action="preview">Preview for family review</button><p class="microcopy">The preview uses changed data. It will not count as delayed evidence or earn credits.</p></div>`;return}const p=ready?track().fresh.challenge:track().fresh.preview,g=p.graph,s=p.summary,reveal=Boolean(work.reveal),sorted=Boolean(work.sorted);if(!work.graph){$('#activity').innerHTML=`<p class="eyebrow">${ready?'DELAYED CHECK · NEW DATA':'FAMILY PREVIEW · NOT DELAYED EVIDENCE'}</p><h3>Find the difference between ${esc(g.labels[g.compare[0]])} and ${esc(g.labels[g.compare[1]])}.</h3>${graphModel(g,reveal)}${numberChoices(g.answer,[Math.abs(g.compare[0]-g.compare[1]),g.values[g.compare[0]]+g.values[g.compare[1]]],'fresh-graph')}<div class="answer-row"><button class="secondary" data-action="show-values">${reveal?'Exact values shown':'Show exact bar values'}</button></div>${controls()}${hint(`The axis counts by ${g.scale}. Translate both heights, then subtract.`)}`;document.querySelectorAll('[data-fresh-graph]').forEach(b=>b.onclick=()=>{if(Number(b.dataset.freshGraph)===g.answer&&graphDifference(g)===g.answer){work={...work,graph:true};saveSession();feedback('The graph comparison is correct. Now describe the new data set.','good');setTimeout(renderMission,350)}else miss('Read both values from the scale before subtracting.')});return}if(!work.summary){$('#activity').innerHTML=`<p class="eyebrow">CHANGED DATA SET</p><h3>Find the ${esc(s.kind)}.</h3>${dataModel(s,sorted)}${numberChoices(s.answer,[Math.max(...s.data),Math.min(...s.data)],'fresh-summary')}<div class="answer-row"><button class="secondary" data-action="sort-data">${sorted?'Values are in order':'Put values in order'}</button></div>${controls()}${hint(s.kind==='mode'?'Find the value that repeats most.':s.kind==='range'?'Subtract least from greatest.':'Order the values and find the middle position.')}`;document.querySelectorAll('[data-fresh-summary]').forEach(b=>b.onclick=()=>{if(Number(b.dataset.freshSummary)===s.answer&&dataSummary(s.data,s.kind)===s.answer){work={...work,summary:true};saveSession();feedback('The data summary is correct. Now connect both results in one proof.','good');setTimeout(renderMission,350)}else miss(`Use the exact meaning of ${s.kind}, not just the largest visible number.`)});return}$('#activity').innerHTML=`<p class="eyebrow">ONE PROOF · TWO RESULTS</p><h3>Difference ${g.answer} · ${esc(s.kind)} ${s.answer}</h3>${graphModel(g,true)}${dataModel(s,true)}${textChoices(p.proof,p.decoys,'fresh-proof')}${controls()}${hint('The proof must name both bar values, the subtraction, and how the ordered data gives the summary.')}`;document.querySelectorAll('[data-fresh-proof]').forEach(b=>b.onclick=()=>{if(b.dataset.freshProof==='correct'){feedback(ready?'You transferred graph and data reasoning to a fresh problem after a delay.':'Preview complete. Return later for fresh evidence.','good');complete(4,['scale','summary','transfer'],false,!ready)}else miss('Reject any proof that ignores the scale or uses the wrong meaning of the data summary.')})}
function renderComplete(i){const m=DATA_CHAIN.missions[i];$('#activity').innerHTML=`<div class="complete-card"><div class="big-check">✓</div><p class="eyebrow">MISSION COMPLETE</p><h3>${esc(m.title)}</h3><p>Your work is saved for ${learner==='a'?'Ella':'Mila'}.</p>${i<4?'<button class="primary" data-action="next">Continue →</button>':'<a class="primary" href="./" style="text-decoration:none">Return home</a>'}</div>`}
function renderMission(){const i=state.activeMission,m=DATA_CHAIN.missions[i];if(sessionMissionId!==m.id)loadSession(m.id);$('#missionEyebrow').textContent=`MISSION ${m.number} · ${m.kind.replace('-',' ').toUpperCase()}`;$('#missionTitle').textContent=m.title;$('#missionObjective').textContent=m.objective;$('#missionTime').textContent=`ABOUT ${m.minutes} MIN`;feedback('');if(done(i)){renderComplete(i);return}if(i===0)renderDiagnostic();else if(i===1)renderGraph();else if(i===2)renderSummary();else if(i===3)renderClaim();else renderFresh()}
function renderNav(){$('#missionNav').innerHTML=DATA_CHAIN.missions.map((m,i)=>`<button class="mission-button ${i===state.activeMission?'active':''} ${unlocked(i)?'':'locked'}" data-mission="${i}" ${unlocked(i)?'':'disabled'}><span class="mission-number">${m.number}</span><span class="mission-label">${esc(m.title)}</span><span class="mission-state">${done(i)?'✓':unlocked(i)?'›':'◌'}</span></button>`).join('');document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>{state.activeMission=Number(b.dataset.mission);sessionMissionId=null;save();render()})}
function renderTrack(){const t=track();$('#trackCard').innerHTML=`<strong>Current depth: ${t.label}</strong><span>${t.description}</span><select id="trackSelect" aria-label="Learning depth">${Object.values(DATA_TRACKS).map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${x.label}</option>`).join('')}</select><small>Changing depth restarts this review path so evidence is not mixed.</small>`;$('#trackSelect').onchange=e=>{state={...createBlankDataLearner(),track:e.target.value,family:state.family};sessionMissionId=null;save();render()}}
function renderEvidence(){const name=learner==='a'?'Ella':'Mila',labels={scale:'Read graph scales',summary:'Describe a data set',claim:'Make fair conclusions',transfer:'Fresh transfer'};$('#evidenceTitle').textContent=`${name}’s learning evidence`;$('#reviewBannerTitle').textContent=`Built for ${name} · waiting family review`;$('#evidenceGrid').innerHTML=Object.entries(labels).map(([k,v])=>`<div class="evidence-item"><header><span>${v}</span><span>${state.evidence[k]==='independent'?'Independent':state.evidence[k]==='learning'?'Learning':'Not checked'}</span></header></div>`).join('')}
function renderFamily(){$('#helpNote').value=state.family.help;$('#explainNote').value=state.family.explain;$('#continueNote').value=state.family.continue}
function render(){ensureState();$('#learnerSelect').value=learner;renderTrack();renderNav();renderEvidence();renderFamily();renderMission()}

document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='start'){state.missions['data-start']={complete:true,score:state.diagnostic.score,completedAt:new Date().toISOString()};state.activeMission=1;sessionMissionId=null;save();render()}else if(a==='next'){state.activeMission=Math.min(4,state.activeMission+1);sessionMissionId=null;save();render()}else if(a==='hint'){hintLevel++;saveSession();renderMission()}else if(a==='show-values'){if(!work.reveal)hintLevel++;work={...work,reveal:true};saveSession();renderMission()}else if(a==='sort-data'){work={...work,sorted:true};saveSession();renderMission()}else if(a==='preview'){state.previewFresh=true;save();render()}});
$('#learnerSelect').onchange=e=>{learner=e.target.value;state=readStore()[learner]||createBlankDataLearner();sessionMissionId=null;ensureState();save();render()};
for(const[id,key]of[['helpNote','help'],['explainNote','explain'],['continueNote','continue']])$('#'+id).addEventListener('input',e=>{state.family[key]=e.target.value;save()});
$('#resetPath').onclick=()=>{if(confirm(`Reset the data and graph review path for ${learner==='a'?'Ella':'Mila'}?`)){state=createBlankDataLearner();sessionMissionId=null;save();render()}};
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('sw.js'));
ensureState();render();
